            "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 법인코드
            "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + // 시작일자
            "&{P}param04=" + $c.stf.getObjectValue(edt_EDate) + // 종료일자
            "&{P}param05=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param06=" + $c.stf.getObjectValue(cmb_DEP_CD_1) + "&{P}param07=" + $c.stf.getObjectValue(cmb_EMP_NO_1) + "&{P}param08=" + $c.stf.getObjectValue(cmb_EMP_NO_1);
    }
    dts_report.DataID = encodeURI(url);
    dts_report.reset();
    var dataFormatArr = ["TASK_DD:FormatDateEx", "LIST_SHRS:FormatNumberEx", "TDD_CLSPRC:FormatNumberEx", "MKTCAP:FormatNumberEx", "CORRCT_MKTCAP:FormatNumberEx", "FST_LACK_DD:FormatDateEx"];
    var jsonData = $c.rpt.fn_make_dtsToJson1_wdf(dts_report, dataFormatArr);
    var userParam = [{
        uid: "SDate",
        unm: $c.stf.getObjectValue(edt_SDate)
    }, {
        uid: "EDate",
        unm: $c.stf.getObjectValue(edt_EDate)
    }, {
        uid: "STATE",
        unm: $c.stf.getObjectValue(txb_TR_STATE_CD)
    }, {
        uid: "jsonData",
        unm: jsonData
    }, {
        uid: "horizontal",
        unm: "y"
    }];

    //PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, scwin.userParam);
};
