    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO_1, '');
    }
    dts_EMP_NO_1.UseFilter = true;
    dts_EMP_NO_1.Filter();
    dts_EMP_NO_1.sort("DEP_CD", 0);
    //dts_EMP_NO_1.sort(); // W-Craft 주석처리 

};
scwin.dts_EMP_NO_1_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO_1.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO_1.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.gform_onload = function() {
    //round처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();

    //오늘날짜로 초기화시킨다.
    //var today = cGetToday("yyyymmdd");
    //var y_day = cGetMinusDate2(today, 1); 	// 하루 전 날짜로 	공시총괄팀 요청
    var y_day = $c.ud.fn_get_search_taskdd(dts_TASK_DD, 'A');
    $c.stf.setObjectValue(edt_SDate, y_day);
    $c.stf.setObjectValue(edt_EDate, y_day);
    if (scwin.svrGubun == "dr") {
        //DR일 경우   2011.01.28
        $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        $c.stf.setObjectValue(txb_TR_STATE_CD, "-");
    } else {
        $c.stf.setObjectValue(txb_TR_STATE_CD, $c.ud.fn_get_trstatcd(dts_TR_STATE_CD, $c.ut.cGetToday("yyyymmdd")));
    }
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    Grd_com_isur.style.zIndex = 30;
};
